server/openrouter/config.js - the one reader every surface uses:
```js
// Stat-gated reader: re-reads + re-validates only when the file mtime changes.
// Never throws. Missing file => ok:true, openrouter off unless the key is set (then the
// built-in panel). Bad JSON => ok:false parse error.
function makeConfigReader(filePath, env = process.env) {
  let cachedMtimeMs = null; let cachedResult = null;
  function read() {
    let raw;
    try { raw = fs.readFileSync(filePath, "utf8"); }
    catch (err) {
      if (err && err.code === "ENOENT") return { ok: true, error: null, resolved: { configLoadState: "missing", version: 1, providers: {}, openrouter: validateConfig({}, env).resolved.openrouter, consensus: {...}, sessions: {...}, dashboard: {...} } };
      return fail(`read failed: ${err.message}`);
    }
    let parsed;
    try { parsed = JSON.parse(raw); } catch (err) { return fail(`JSON parse failed: ${err.message}`); }
    return validateConfig(parsed, env);
  }
  return { get() {
    let mtimeMs = null; try { mtimeMs = fs.statSync(filePath).mtimeMs; } catch (_) { mtimeMs = null; }
    if (cachedResult === null || mtimeMs !== cachedMtimeMs) { cachedResult = read(); cachedMtimeMs = mtimeMs; }
    return cachedResult;
  } };
}
// fail(message) => { ok: false, resolved: null, error: message }
```

